    final class RadarScopeView extends View {
        final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);
        RadarScopeView(Context context){super(context);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}
        void label(Canvas c,String text,float x,float y,int size,int color){p.setStyle(Paint.Style.FILL);p.setTypeface(Typeface.MONOSPACE);p.setTextSize(dp(size));p.setColor(color);c.drawText(text,x,y,p);}
        @Override protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight(),cx=w*0.31f,cy=dp(99),radius=Math.min(w*0.275f,dp(86));p.setStyle(Paint.Style.FILL);p.setColor(PANEL);c.drawRect(0,0,w,h,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(0.6f));p.setColor(GRID);c.drawRect(0.5f,0.5f,w-0.5f,h-0.5f,p);
            for(int i=1;i<=4;i++)c.drawCircle(cx,cy,radius*i/4f,p);c.drawLine(cx-radius-dp(5),cy,cx+radius+dp(5),cy,p);c.drawLine(cx,cy-radius-dp(5),cx,cy+radius+dp(5),p);
            for(int i=0;i<=40;i++){double angle=Math.toRadians(135+i*6.75);float inner=radius+dp(i%5==0?3:5),outer=radius+dp(8);p.setColor(i%5==0?DIM:GRID);c.drawLine(cx+(float)Math.cos(angle)*inner,cy+(float)Math.sin(angle)*inner,cx+(float)Math.cos(angle)*outer,cy+(float)Math.sin(angle)*outer,p);}
            int strongestWifi=-127,strongestBle=-127,wifiCount=0,bleCount=0;int[][] bins=new int[2][5];long now=System.currentTimeMillis();for(Row r:snapshot()){if(now-r.lastSeen>60000||r.rssi>=0||r.rssi< -127)continue;int kind=r.kind.trim().equals("BLE")?1:0;bins[kind][Math.max(0,Math.min(4,(r.rssi+110)/18))]++;if(kind==0){wifiCount++;strongestWifi=Math.max(strongestWifi,r.rssi);}else{bleCount++;strongestBle=Math.max(strongestBle,r.rssi);}}
            gauge(c,cx,cy,radius-dp(3),strongestWifi,AMBER);gauge(c,cx,cy,radius-dp(12),strongestBle,BLUE);
            label(c,String.format(Locale.US,"%03d",wifiCount+bleCount),cx-dp(25),cy+dp(5),25,WHITE);label(c,"ACTIVE 60s",cx-dp(26),cy+dp(21),8,DIM);label(c,"-110",cx-radius*0.77f,cy+radius*0.83f,7,DIM);label(c,"-20",cx+radius*0.48f,cy+radius*0.83f,7,DIM);
            float x=w*0.65f;label(c,"PEAK RSSI",x,dp(27),8,DIM);label(c,"WIFI",x,dp(52),9,AMBER);label(c,strongestWifi== -127?"—":strongestWifi+"",x,dp(75),21,AMBER);label(c,"BLE",x,dp(101),9,BLUE);label(c,strongestBle== -127?"—":strongestBle+"",x,dp(124),21,BLUE);label(c,"dBm",x,dp(143),8,DIM);
            float left=dp(13),right=w-dp(13),base=h-dp(19),barTop=dp(193),step=(right-left)/5f;int max=1;for(int i=0;i<5;i++)max=Math.max(max,bins[0][i]+bins[1][i]);label(c,"RSSI DISTRIBUTION",left,dp(183),7,DIM);label(c,"MAX "+max,right-dp(43),dp(183),7,DIM);
            for(int i=0;i<5;i++){float bx=left+i*step,bw=step-dp(8),wh=(base-barTop)*bins[0][i]/max,bh=(base-barTop)*bins[1][i]/max;p.setStyle(Paint.Style.FILL);p.setColor(GRID);c.drawRect(bx,barTop,bx+bw,base,p);p.setColor(AMBER);c.drawRect(bx,base-wh,bx+bw,base,p);p.setColor(BLUE);c.drawRect(bx,base-wh-bh,bx+bw,base-wh,p);label(c,new String[]{"-110","-92","-74","-56","-38"}[i],bx,base+dp(12),7,DIM);}
        }
        void gauge(Canvas c,float x,float y,float radius,int rssi,int color){if(rssi== -127)return;float sweep=Math.max(0,Math.min(1,(rssi+110)/90f))*270;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(2));p.setColor(color);c.drawArc(x-radius,y-radius,x+radius,y+radius,135,sweep,false,p);double angle=Math.toRadians(135+sweep);float px=x+(float)Math.cos(angle)*radius,py=y+(float)Math.sin(angle)*radius;p.setStyle(Paint.Style.FILL);c.drawCircle(px,py,dp(3),p);}
    }
