    final HashMap<String,CardHolder> cardCache=new HashMap<>();
    final HashMap<String,ThreatRules.SsidBaseline> ssidBaselines=new HashMap<>();
    final ArrayDeque<Long> bleAddrFirstSeen=new ArrayDeque<>(); final HashSet<String> bleAddrEver=new HashSet<>(); String swarmAlert="";
    void noteBleAddress(String mac){long now=System.currentTimeMillis();synchronized(bleAddrFirstSeen){if(bleAddrEver.add(mac))bleAddrFirstSeen.addLast(now);while(!bleAddrFirstSeen.isEmpty()&&now-bleAddrFirstSeen.peekFirst()>60000)bleAddrFirstSeen.removeFirst();}}
    int bleSwarmCount(){synchronized(bleAddrFirstSeen){long now=System.currentTimeMillis();while(!bleAddrFirstSeen.isEmpty()&&now-bleAddrFirstSeen.peekFirst()>60000)bleAddrFirstSeen.removeFirst();return bleAddrFirstSeen.size();}}
    void runThreatRules(){ArrayList<Row> all=snapshot();ThreatRules.evaluate(all,ssidBaselines,System.currentTimeMillis());ThreatRules.Flag swarm=ThreatRules.bleSwarm(bleSwarmCount());swarmAlert=swarm==null?"":swarm.label+"  ·  "+swarm.evidence;ArrayList<String> here=new ArrayList<>();for(Row r:all)if(r.kind.trim().equals("WIFI")&&r.rssi>=-80)here.add(r.mac);locationTracker.setLocation(here);applyHotspotCorrelation(all);}
    static final String LINK_SEP=" ⟐ ";   // marks the idempotently-rebuilt co-presence note on a hotspot row's evidence (a char that appears in no base evidence)
    // Phase 7 (§6.4): classify an active iOS Personal Hotspot from its Apple vendor IE. The device IS
    // Apple hardware (the IE OUI 0017F2 is Apple's), so attribute "Apple" directly — do NOT run a vendor
    // lookup on the attacker-controllable BT-MAC payload bytes. Spec LOW. Never overwrite a higher-value
    // public-safety / camera / tracker classification — append the note to its evidence instead.
    void applyHotspot(Row r){if(r.raw==null||!r.kind.trim().equals("WIFI"))return;HotspotCorrelator.Identity hp=HotspotCorrelator.detect(r.mac,r.raw.optString("informationElements",""));if(hp==null)return;boolean strong=hp.consistency==HotspotCorrelator.Consistency.STRONG;String note=(strong?"strong · ":"weak · ")+"Apple hotspot IE 221/0017F2 type-6 carries a globally-administered BT MAC"+(strong?" matching the BSSID lower octets (±1)":", BSSID cross-check inconclusive")+" — hardware made by Apple, does NOT indicate any agency or person is present";if(r.publicSafety||r.camera||r.tracker){r.classificationEvidence=r.classificationEvidence.isEmpty()?note:r.classificationEvidence+" · "+note;return;}r.classification="iOS PERSONAL HOTSPOT (active) · BT "+hp.btMac;r.classificationEvidence=note;}
    // Phase 7 (§6.4): weak, label-only BLE<->hotspot co-presence join over the shared RSSI series; never
    // an alert, never deterministic. Rebuilds (not accumulates) the note each pass via LINK_SEP, so the
    // per-draw call can't grow the evidence string without bound; series are precomputed once per MAC.
    void applyHotspotCorrelation(ArrayList<Row> all){ArrayList<Row> hotspots=new ArrayList<>(),appleBle=new ArrayList<>();for(Row r:all){if(r.raw==null)continue;if(r.kind.trim().equals("WIFI")){if(HotspotCorrelator.detect(r.mac,r.raw.optString("informationElements",""))!=null)hotspots.add(r);}else if(r.kind.trim().equals("BLE")&&!ContinuityParser.apple(r.raw.optString("manufacturer","")).isEmpty())appleBle.add(r);}if(hotspots.isEmpty()||appleBle.isEmpty())return;ArrayList<SignalPoint> hist;synchronized(signalHistory){hist=new ArrayList<>(signalHistory);}long now=System.currentTimeMillis();java.util.HashMap<String,java.util.List<long[]>> bleSeries=new java.util.HashMap<>();for(Row b:appleBle)bleSeries.put(b.mac,series(hist,"BLE",b.mac));for(Row w:hotspots){java.util.List<long[]> ws=series(hist,"WIFI",w.mac);HotspotCorrelator.Link link=null;for(Row b:appleBle){link=HotspotCorrelator.consecutiveMac(w.mac,b.mac);if(link==null)link=HotspotCorrelator.coPresence(ws,bleSeries.get(b.mac),w.firstSeen,b.firstSeen,now,"RANDOM_RPA".equals(bleAddrType(b.mac)));if(link!=null)break;}int cut=w.classificationEvidence.indexOf(LINK_SEP);String base=cut>=0?w.classificationEvidence.substring(0,cut):w.classificationEvidence;w.classificationEvidence=link==null?base:(base.isEmpty()?link.evidence:base+LINK_SEP+link.evidence);}}
    java.util.List<long[]> series(java.util.List<SignalPoint> hist,String kind,String mac){ArrayList<long[]> out=new ArrayList<>();for(SignalPoint s:hist)if(s.kind.equals(kind)&&mac.equals(s.mac))out.add(new long[]{s.time,s.rssi});out.sort((p,q)->Long.compare(p[0],q[0]));return out;}
