    FinderView finderView; String finderKey="";
    void feedFinder(Row r){if(finderView==null||!page.equals("FINDER"))return;if((r.kind+"|"+r.mac).equals(finderKey))finderView.update(r.rssi);}
    void logDevice(Row r){double lat=r.observations.hasLocation()?r.observations.lastLat:Double.NaN,lon=r.observations.hasLocation()?r.observations.lastLon:Double.NaN;detectionLog.record(r.kind.trim()+"|"+r.mac,r.kind.trim(),r.mac,r.vendor,r.classification.isEmpty()?r.threat:r.classification,r.name,r.source,r.rssi,lat,lon,r.observations.lastFixAt,r.raw==null?null:r.raw.toString(),System.currentTimeMillis());String sid=stableId(r);if(sid!=null){String al=locationTracker.observe(sid,r.classification.isEmpty()?r.vendor:r.classification);if(al!=null)notifyFollow("loc:"+sid,al);}}
    // Phase 6 (§6.5): most-stable identifier for the GPS-free "following me across places" check — a
    // separated tracker's payload id, never its rotating MAC. shortcut: only separated-tracker ids feed
    // this yet; Fast Pair model id / AirPods pseudo-id aren't plumbed onto Row — add them to widen coverage.
    String stableId(Row r){if(r.raw==null)return null;SeparatedTracker.Hit h=SeparatedTracker.detect(r.mac,r.raw.optString("manufacturer",""),r.raw.optJSONObject("serviceData"));return h==null?null:h.stableId;}
    void exportSession(){new Thread(()->{try{String[] paths=detectionLog.export(this);runOnUiThread(()->{log("CSV → "+paths[0]);log("KML → "+paths[1]);log("JSON → "+paths[2]);toast("Exported "+detectionLog.size()+" devices to app files dir");shareFiles(paths);draw();});}catch(Exception e){runOnUiThread(()->{log("export failed: "+e.getMessage());toast("Export failed");draw();});}}).start();}
    void toast(String s){try{Toast.makeText(this,s,Toast.LENGTH_LONG).show();}catch(Exception ignored){}}
    void shareFiles(String[] paths){try{android.net.Uri csv=fileUri(new File(paths[0]));if(csv==null)return;Intent send=new Intent(Intent.ACTION_SEND).setType("text/csv").putExtra(Intent.EXTRA_STREAM,csv).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(send,"Export SWIVEL session"));}catch(Exception e){log("share unavailable; files saved to app dir");}}
    android.net.Uri fileUri(File f){try{return FileShareProvider.uriFor(this,f);}catch(Throwable t){return null;}}
    void duressClear(){detectionLog.clear();detectionLog.wipeExports(this);synchronized(rows){rows.clear();}cardCache.clear();synchronized(signalHistory){signalHistory.clear();}synchronized(logs){logs.clear();}ssidBaselines.clear();locationTracker.clear();synchronized(bleAddrFirstSeen){bleAddrFirstSeen.clear();bleAddrEver.clear();}swarmAlert="";attackAlert="";log("session cleared");page="LIVE";draw();}
    static final String FOLLOW_CHANNEL="follow_alert"; boolean followChannelReady=false;
    void feedFollowDetector(Row r){if(!r.tracker)return;if(!r.observations.hasLocation())return;String key=FollowDetector.identityKey(r.mac,r.raw);String label=r.classification.isEmpty()?r.vendor:r.classification;String alert=followDetector.observe(key,label,r.observations.lastLat,r.observations.lastLon,System.currentTimeMillis());if(alert!=null)notifyFollow(key,alert);}
    // Phase 1 (§6.1): separated-tracker hits route through the precise detector; other trackers keep the generic follow path.
    void feedTrackerDetection(Row r){SeparatedTracker.Hit hit=r.raw==null?null:SeparatedTracker.detect(r.mac,r.raw.optString("manufacturer",""),r.raw.optJSONObject("serviceData"));if(hit!=null){r.tracker=true;r.classification=hit.label;r.classificationEvidence=hit.evidence;if(r.observations.hasLocation()){String alert=separatedDetector.observe(hit.stableId,hit.label,r.observations.lastLat,r.observations.lastLon,System.currentTimeMillis());if(alert!=null)notifyFollow("sep:"+hit.stableId,alert);}return;}if(r.tracker)feedFollowDetector(r);}
    // Phase 3 (§5): verified LE/gov/surveillance vendor prefix -> specificity-weighted result, with the "not an agency" framing.
    void applyVendorTable(Row r){VendorTable.V v=VendorTable.lookup(r.mac);if(v==null)return;r.publicSafety=true;if(v.camera)r.camera=true;r.classification="PUBLIC SAFETY · "+v.org+" ["+v.spec+"]";r.classificationEvidence=VendorTable.framing(v);}
    // Phase 4 (§6.2/§6.3): enrich a BLE device with cleartext Continuity / Fast Pair / Swift Pair intel.
    void applyDeviceIntel(Row r){if(r.raw==null)return;String mf=r.raw.optString("manufacturer","");StringBuilder d=new StringBuilder();String ap=ContinuityParser.apple(mf);if(!ap.isEmpty())d.append("Apple Continuity: ").append(ap);String sp=ContinuityParser.swiftPair(mf);if(!sp.isEmpty()){if(d.length()>0)d.append(" · ");d.append(sp);}org.json.JSONObject sd=r.raw.optJSONObject("serviceData");if(sd!=null){java.util.Iterator<String> it=sd.keys();while(it.hasNext()){String u=it.next();if(SeparatedTracker.uuid16(u).equals("FE2C")){String fp=ContinuityParser.fastPair(sd.optString(u,""));if(!fp.isEmpty()){if(d.length()>0)d.append(" · ");d.append(fp);}}}}if(d.length()==0)return;if(r.classification.isEmpty()||r.classification.equals("BLE ADVERTISEMENT"))r.classification="DEVICE INTEL · "+d;r.classificationEvidence=r.classificationEvidence.isEmpty()?d.toString():r.classificationEvidence+" · "+d;}
    void notifyFollow(String key,String message){try{NotificationManager nm=getSystemService(NotificationManager.class);if(!followChannelReady){nm.createNotificationChannel(new NotificationChannel(FOLLOW_CHANNEL,"Follow alerts",NotificationManager.IMPORTANCE_HIGH));followChannelReady=true;}PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(this,FOLLOW_CHANNEL).setSmallIcon(R.drawable.ic_millie_status).setContentTitle("Possible tracker following you").setContentText(message).setStyle(new Notification.BigTextStyle().bigText(message)).setContentIntent(open).setAutoCancel(true).build();nm.notify(("follow:"+key).hashCode(),n);log("FOLLOW "+message);}catch(Exception e){log("follow alert failed");}}
    String attackAlert=""; long attackAlertAt;
    void handleAttackReport(JSONObject j){int de=j.optInt("deauth",0),di=j.optInt("disassoc",0),pr=j.optInt("probe_req",0);int floods=de+di;if(floods>=10){attackAlert="UNDER ATTACK · "+de+" deauth / "+di+" disassoc per sec (CYD · ch "+j.optInt("ch",0)+")";attackAlertAt=System.currentTimeMillis();log("CYD attack: deauth="+de+" disassoc="+di+" probe_req="+pr);}else if(pr>=60){attackAlert="PROBE HARVESTING · "+pr+" probe-requests per sec (CYD)";attackAlertAt=System.currentTimeMillis();log("CYD probe harvest: "+pr+"/s");}else if(System.currentTimeMillis()-attackAlertAt>8000)attackAlert="";}
    String bandLabel(Row d){if(!d.kind.trim().equals("WIFI")||d.raw==null)return "";int f=d.raw.optInt("frequencyMHz",0);if(f>=2400&&f<2500)return "2.4 GHz";if(f>=4900&&f<5900)return "5 GHz";if(f>=5925&&f<=7125)return "6 GHz";return "";}
    String cachedLabel(Row d){if(!d.kind.trim().equals("WIFI"))return "";long age=System.currentTimeMillis()-d.lastSeen;if(age<=45000)return "";long sec=age/1000;return sec<120?"cached "+sec+"s":"cached "+sec/60+"m";}
    static final int ROW_CAP=600;
    void evictRows(){synchronized(rows){while(rows.size()>ROW_CAP){String victim=null;long oldest=Long.MAX_VALUE;for(Map.Entry<String,Row> e:rows.entrySet()){Row r=e.getValue();if(r.camera||r.tracker||r.publicSafety)continue;if(r.lastSeen<oldest){oldest=r.lastSeen;victim=e.getKey();}}if(victim==null)break;rows.remove(victim);final String vk=victim;scanHandler.post(()->cardCache.remove(vk));}}}
    void build(){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(BG);root.setPadding(dp(14),dp(12),dp(14),dp(8));setContentView(root);
        LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);title=text("SWIVEL",27,GREEN,false);title.setLetterSpacing(0.16f);head.addView(title,new LinearLayout.LayoutParams(0,-2,1));link=text("● OFFLINE",9,PINK,false);link.setLetterSpacing(0.08f);head.addView(link);root.addView(head);
        TextView sub=text("CIVOPS     2.0.14",8,DIM,false);sub.setLetterSpacing(0.18f);sub.setPadding(dp(1),dp(6),0,dp(13));root.addView(sub);
        stats=text("WIFI 000   BLE 000   CONTACTS 000",9,WHITE,false);stats.setLetterSpacing(0.04f);stats.setPadding(0,dp(9),0,dp(9));root.addView(stats);
        LinearLayout controls=new LinearLayout(this);controls.setPadding(0,0,0,dp(9));Button connect=button("CYD LINK",GREEN);connect.setOnClickListener(v->connect());controls.addView(connect,new LinearLayout.LayoutParams(0,dp(44),1));Button scan=button("PHONE SCAN",PINK);scan.setOnClickListener(v->ensurePhoneScan());LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(0,dp(44),1);sp.leftMargin=dp(8);controls.addView(scan,sp);root.addView(controls);
        ScrollView sc=new ScrollView(this);pageScroll=sc;sc.setFillViewport(true);sc.setVerticalScrollBarEnabled(false);body=new LinearLayout(this);body.setOrientation(1);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
        nav=new LinearLayout(this);nav.setPadding(0,dp(8),0,0);String[] pages={"LIVE","CAMERAS","TRACKERS","PUBLIC SAFETY","MORE"};for(String destination:pages){TextView n=text(destination.equals("PUBLIC SAFETY")?"PUBLIC\nSAFETY":destination,8,DIM,false);n.setGravity(Gravity.CENTER);n.setTag(destination);n.setLetterSpacing(0.025f);n.setMinHeight(dp(48));n.setOnClickListener(v->{page=destination;draw();sc.scrollTo(0,0);});nav.addView(n,new LinearLayout.LayoutParams(0,dp(48),1));}root.addView(nav);draw();}
    Button button(String s,int color){Button b=new Button(this);b.setText(s);b.setTextColor(color);b.setTextSize(9);b.setLetterSpacing(0.08f);b.setTypeface(Typeface.MONOSPACE,Typeface.NORMAL);b.setAllCaps(false);b.setMinHeight(dp(40));b.setMinimumHeight(dp(40));b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(8),0,dp(8),0);android.graphics.drawable.StateListDrawable states=new android.graphics.drawable.StateListDrawable();states.addState(new int[]{android.R.attr.state_pressed},surface(color,0xFF122019));states.addState(new int[]{},surface(GRID,PANEL));b.setBackground(states);return b;}
    void refreshNav(){String active=page.equals("DETAIL")||page.equals("FINDER")?returnPage:(page.equals("LOG")||page.equals("LINK")||page.equals("SUSPECT")||page.equals("COLLECTOR")?"MORE":page);for(int i=0;i<nav.getChildCount();i++){TextView n=(TextView)nav.getChildAt(i);boolean selected=active.equals(n.getTag());n.setTextColor(selected?PINK:DIM);n.setBackground(new android.graphics.drawable.Drawable(){final Paint paint=new Paint();public void draw(Canvas c){paint.setColor(selected?PINK:GRID);c.drawRect(0,0,getBounds().width(),dp(selected?2:1),paint);if(selected){paint.setColor(0x0FFF55B8);c.drawRect(0,dp(2),getBounds().width(),getBounds().height(),paint);}}public void setAlpha(int a){}public void setColorFilter(android.graphics.ColorFilter f){}public int getOpacity(){return android.graphics.PixelFormat.TRANSLUCENT;}});}}
    void draw(){body.removeAllViews();if(!page.equals("FINDER")&&finderView!=null){finderView.stop();finderView=null;}runThreatRules();if(page.equals("LIVE")){section("SIGNAL SCOPE");body.addView(new RadarScopeView(this),new LinearLayout.LayoutParams(-1,dp(238)));if(!attackAlert.isEmpty()&&System.currentTimeMillis()-attackAlertAt<8000)line(attackAlert,PINK);if(!swarmAlert.isEmpty())line(swarmAlert,PINK);section("CONTACTS");if(rows.isEmpty())line(phoneActive?"SCANNING PHONE RADIOS":"ENABLE PHONE SCAN",DIM);ArrayList<Row> contacts=snapshot();contacts.sort(Comparator.comparingLong((Row r)->r.lastSeen).reversed());for(Row d:contacts)addSignalCard(d);}
        else if(page.equals("SUSPECT")||page.equals("COLLECTOR")){drawThreatPage(page);}
        else if(page.equals("FINDER")){drawFinder();}
        else if(page.equals("DETAIL")){if(selectedRow==null){page="LIVE";draw();return;}Row d=selectedRow;int accent=d.kind.equals("BLE ")?BLUE:AMBER;Button back=button("←  "+returnPage,PINK);back.setOnClickListener(v->{page=returnPage;draw();pageScroll.post(()->pageScroll.scrollTo(0,0));});body.addView(back);Button find=button("FIND THIS DEVICE  ·  HOT/COLD",GREEN);find.setOnClickListener(v->{page="FINDER";draw();pageScroll.post(()->pageScroll.scrollTo(0,0));});body.addView(find);
            LinearLayout identity=new LinearLayout(this);identity.setOrientation(1);identity.setPadding(dp(12),dp(11),dp(12),dp(10));identity.setBackgroundColor(PANEL);LinearLayout.LayoutParams ilp=new LinearLayout.LayoutParams(-1,-2);ilp.topMargin=dp(5);body.addView(identity,ilp);
            TextView protocol=text(d.kind.equals("BLE ")?"BLE  /  ADVERTISEMENT":"WI-FI  /  "+(d.raw==null?"FRAME":d.raw.optString("ftype","FRAME").replace("_"," ")),9,accent,false);protocol.setLetterSpacing(0.08f);identity.addView(protocol);
            String display=d.name.isEmpty()?d.mac:d.name;TextView primary=text(display,16,WHITE,false);primary.setPadding(0,dp(5),0,dp(2));identity.addView(primary);
            if(!d.name.isEmpty()){TextView address=text(d.mac,10,DIM,false);identity.addView(address);}
            TextView manufacturer=text(d.vendor+(d.oui.isEmpty()?"":"  ·  OUI "+formatOui(d.oui)),9,DIM,false);manufacturer.setPadding(0,dp(4),0,0);identity.addView(manufacturer);
            section("SIGNAL PROFILE  ·  LAST 48 READINGS");body.addView(new SignalGraphView(this,d.mac,d.kind.trim()),new LinearLayout.LayoutParams(-1,dp(158)));body.addView(metricStrip(d));
            section("SWIVEL CLASSIFICATION");TextView classification=text(d.classification.isEmpty()?"UNCLASSIFIED":d.classification,11,PINK,false);classification.setPadding(dp(2),dp(1),0,dp(3));body.addView(classification);if(!d.classificationEvidence.isEmpty())line(d.classificationEvidence,DIM);
            section("OBSERVATION DATA");metadataItem("SOURCE",d.source);for(ObservationState.Sample sample:d.observations.sources.values())metadataItem(sample.source,sample.rssi+" dBm · "+sample.count+" readings · "+ageLabel(sample.observedAt));metadataItem("FIRST SEEN",ageLabel(d.firstSeen));metadataItem("LAST SEEN",ageLabel(d.lastSeen));
            section(d.kind.equals("BLE ")?"ADVERTISEMENT FIELDS":"RADIO FIELDS");addCapturedData(d);}
        else if(page.equals("CAMERAS")||page.equals("TRACKERS")||page.equals("PUBLIC SAFETY")){drawClassifiedPage(page);}
        else if(page.equals("MORE")){section("THREAT");int suspectN=0,collN=0;for(Row r:snapshot()){if(r.collector)collN++;else if(r.suspect)suspectN++;}Button suspectBtn=button("SUSPECT NETWORKS  /  "+String.format(Locale.US,"%02d",suspectN),suspectN>0?PINK:DIM);suspectBtn.setOnClickListener(v->{page="SUSPECT";draw();});body.addView(suspectBtn);Button collBtn=button("COLLECTOR SIGNALS  /  "+String.format(Locale.US,"%02d",collN),collN>0?PINK:DIM);collBtn.setOnClickListener(v->{page="COLLECTOR";draw();});body.addView(collBtn);section("DEVICE LOG  /  "+String.format(Locale.US,"%04d",detectionLog.size()));Button exportBtn=button("EXPORT CSV · KML · JSON",GREEN);exportBtn.setOnClickListener(v->exportSession());body.addView(exportBtn);Button duressBtn=button("DURESS · CLEAR ALL",PINK);duressBtn.setOnClickListener(v->duressClear());body.addView(duressBtn);section("TOOLS");Button logBtn=button("EVENT LOG",DIM);logBtn.setOnClickListener(v->{page="LOG";draw();});body.addView(logBtn);Button linkBtn=button("CYD LINK",GREEN);linkBtn.setOnClickListener(v->{page="LINK";draw();});body.addView(linkBtn);}
        else if(page.equals("LOG")){section("EVENT LOG");for(int i=logs.size()-1;i>=0;i--)line(logs.get(i),DIM);if(logs.isEmpty())line("NO EVENTS YET",DIM);}
        else {section("DEVICE LINK");line(gotAlive?"FIRMWARE ONLINE":"USB OTG DISCONNECTED",gotAlive?GREEN:AMBER);line("TOUCH  "+touchController+"  ·  "+(touchCalibrated?"CALIBRATED":"UNCALIBRATED"),touchReady?GREEN:AMBER);Button touch=button("TOUCH STATUS",GREEN);touch.setOnClickListener(v->send("CMD|touch|status"));body.addView(touch);Button cal=button("CALIBRATE CYD TOUCH",PINK);cal.setOnClickListener(v->send("CMD|touch|calibrate"));body.addView(cal);Button bleBtn=button("BLE MODE",GREEN);bleBtn.setOnClickListener(v->send("CMD|mode|ble"));body.addView(bleBtn);Button wifiBtn=button("WIFI MODE",GREEN);wifiBtn.setOnClickListener(v->send("CMD|mode|wifi"));body.addView(wifiBtn);Button autoBtn=button("AUTO MODE",PINK);autoBtn.setOnClickListener(v->send("CMD|mode|auto"));body.addView(autoBtn);}
        int wc=0,bc=0;for(Row r:snapshot()){if(r.kind.trim().equals("BLE"))bc++;else wc++;}stats.setText(String.format(Locale.US,"WIFI %03d   BLE %03d   CONTACTS %03d",wc,bc,wc+bc));refreshNav();link.setText(gotAlive?(phoneActive?"● PHONE + CYD":"● CYD"):phoneActive?"● PHONE":"● OFFLINE");link.setTextColor(gotAlive?GREEN:phoneActive?BLUE:PINK);
    }
    CardHolder buildCard(){CardHolder h=new CardHolder();LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(10),dp(12),dp(10),dp(11));card.setBackground(surface(GRID,PANEL));card.setClickable(true);card.setFocusable(true);
        LinearLayout heading=new LinearLayout(this);heading.setGravity(Gravity.CENTER_VERTICAL);h.radio=text("",8,DIM,false);h.radio.setLetterSpacing(0.08f);heading.addView(h.radio,new LinearLayout.LayoutParams(dp(42),-2));h.name=text("",12,WHITE,false);h.name.setSingleLine(true);h.name.setEllipsize(android.text.TextUtils.TruncateAt.END);heading.addView(h.name,new LinearLayout.LayoutParams(0,-2,1));h.strength=text("",15,DIM,false);h.strength.setPadding(dp(10),0,0,0);heading.addView(h.strength);TextView unit=text(" dBm",8,DIM,false);heading.addView(unit);card.addView(heading);
        h.match=text("",9,PINK,false);h.match.setPadding(0,dp(8),0,0);card.addView(h.match);
        LinearLayout footer=new LinearLayout(this);footer.setPadding(0,dp(7),0,0);h.address=text("",9,DIM,false);footer.addView(h.address,new LinearLayout.LayoutParams(0,-2,1));h.source=text("",8,DIM,false);footer.addView(h.source);card.addView(footer);
        card.setOnClickListener(v->{Object tag=card.getTag();if(tag instanceof Row){returnPage=page;selectedRow=(Row)tag;page="DETAIL";draw();pageScroll.post(()->pageScroll.scrollTo(0,0));}});h.card=card;return h;}
    void bindCard(CardHolder h,Row d){int accent=d.kind.trim().equals("BLE")?BLUE:AMBER;h.card.setTag(d);
        h.radio.setText(d.kind.trim());h.radio.setTextColor(accent);
        String band=bandLabel(d);String label=d.name.isEmpty()?(d.publicSafety&&d.classification.startsWith("PUBLIC SAFETY · ")?d.classification.substring("PUBLIC SAFETY · ".length()):d.vendor):d.name;if(!band.isEmpty())label=label+"  ·  "+band;String cached=cachedLabel(d);if(!cached.isEmpty())label=label+"  ·  "+cached;h.name.setText(label);
        h.strength.setText(String.valueOf(d.rssi));h.strength.setTextColor(accent);
        if(d.suspect||d.collector){h.match.setText(d.threat.isEmpty()?d.classification:d.threat);h.match.setVisibility(View.VISIBLE);}else if(d.camera||d.tracker||d.publicSafety){h.match.setText(d.classification);h.match.setVisibility(View.VISIBLE);}else h.match.setVisibility(View.GONE);
        h.address.setText(d.mac);h.source.setText(d.source+"  ·  "+d.count);}
    void addSignalCard(Row d){String key=d.kind+"|"+d.mac;CardHolder h=cardCache.get(key);if(h==null){h=buildCard();cardCache.put(key,h);}bindCard(h,d);if(h.card.getParent() instanceof ViewGroup)((ViewGroup)h.card.getParent()).removeView(h.card);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(6);body.addView(h.card,lp);}
    void drawFinder(){if(selectedRow==null){page=returnPage;draw();return;}Row d=selectedRow;finderKey=d.kind+"|"+d.mac;int accent=d.kind.trim().equals("BLE")?BLUE:AMBER;
        Button back=button("←  BACK",PINK);back.setOnClickListener(v->{if(finderView!=null){finderView.stop();finderView=null;}page="DETAIL";draw();});body.addView(back);
        String tag=d.name.isEmpty()?d.vendor:d.name;if(finderView!=null)finderView.stop();finderView=new FinderView(this,tag,BG,accent,DIM,WHITE);finderView.update(d.rssi);body.addView(finderView,new LinearLayout.LayoutParams(-1,dp(420)));
        String key=FollowDetector.identityKey(d.mac,d.raw);
        Button safe=button("MARK AS SAFE (MY TAG)",GREEN);safe.setOnClickListener(v->{followDetector.markSafe(key);log("marked safe: "+tag);toast("Added to safe list");});body.addView(safe);
        Button mute=button("MUTE THIS TRACKER",DIM);mute.setOnClickListener(v->{followDetector.mute(key);log("muted: "+tag);toast("Muted");});body.addView(mute);}
    void drawThreatPage(String category){boolean coll=category.equals("COLLECTOR");ArrayList<Row> matches=new ArrayList<>();for(Row r:snapshot())if(coll?r.collector:(r.suspect&&!r.collector))matches.add(r);matches.sort(Comparator.comparingLong((Row r)->r.lastSeen).reversed());section(String.format(Locale.US,"%s   /   %02d",category,matches.size()));if(coll&&!swarmAlert.isEmpty())line(swarmAlert,PINK);if(matches.isEmpty()){line(phoneActive?"NO "+category+" SIGNALS":"START PHONE SCAN",DIM);return;}for(Row d:matches){addSignalCard(d);if(!d.threatEvidence.isEmpty())line(d.threatEvidence,DIM);}}
    void drawClassifiedPage(String category){ArrayList<Row> matches=new ArrayList<>();for(Row r:snapshot())if(category.equals("CAMERAS")?r.camera:category.equals("TRACKERS")?r.tracker:r.publicSafety)matches.add(r);String title=category.equals("CAMERAS")?"CAMERAS":category.equals("TRACKERS")?"TRACKERS":"PUBLIC SAFETY";section(String.format(Locale.US,"%s   /   %02d",title,matches.size()));if(matches.isEmpty()){line(phoneActive?"NO MATCHES IN CURRENT SCAN":"START PHONE SCAN",DIM);return;}for(Row d:matches)addSignalCard(d);}
    void ensurePhoneScan(){ArrayList<String> p=new ArrayList<>();if(Build.VERSION.SDK_INT>=31){if(!hasPermission(android.Manifest.permission.BLUETOOTH_SCAN))p.add(android.Manifest.permission.BLUETOOTH_SCAN);if(!hasPermission(android.Manifest.permission.BLUETOOTH_CONNECT))p.add(android.Manifest.permission.BLUETOOTH_CONNECT);}if(!hasPermission(android.Manifest.permission.ACCESS_FINE_LOCATION))p.add(android.Manifest.permission.ACCESS_FINE_LOCATION);if(!p.isEmpty()){requestPermissions(p.toArray(new String[0]),71);log("phone scan permission requested");return;}startPhoneScans();ensureBackgroundLocation();}
    boolean hasPermission(String p){return Build.VERSION.SDK_INT<23||checkSelfPermission(p)==android.content.pm.PackageManager.PERMISSION_GRANTED;}
    boolean hasPhoneScanPermissions(){return hasPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)&&(Build.VERSION.SDK_INT<31||hasPermission(android.Manifest.permission.BLUETOOTH_SCAN));}
    @Override public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] grantResults){super.onRequestPermissionsResult(requestCode,permissions,grantResults);if(requestCode==71){if(hasPhoneScanPermissions()){startPhoneScans();ensureBackgroundLocation();}else{log("phone scan permission denied");draw();}}else if(requestCode==72){log(hasPermission(android.Manifest.permission.ACCESS_BACKGROUND_LOCATION)?"background location granted":"background location denied (screen-off follow limited)");}}
    void ensureBackgroundLocation(){if(Build.VERSION.SDK_INT<29)return;if(hasPermission(android.Manifest.permission.ACCESS_BACKGROUND_LOCATION))return;if(!hasPermission(android.Manifest.permission.ACCESS_FINE_LOCATION))return;try{requestPermissions(new String[]{android.Manifest.permission.ACCESS_BACKGROUND_LOCATION},72);log("background location requested");}catch(Exception ignored){}}
    void startPhoneScans(){if(!hasPhoneScanPermissions()){draw();return;}phoneActive=true;if(!phoneBleActive)startBleScan();scanWifi();draw();scanHandler.removeCallbacks(wifiRepeater);scanHandler.postDelayed(wifiRepeater,30000);scanHandler.removeCallbacks(bleRepeater);scanHandler.postDelayed(bleRepeater,BLE_RESTART_MS);startScanService();startClassicDiscovery();}
    void startScanService(){try{startForegroundService(new Intent(this,ScanService.class));if(!scanServiceBound)bindService(new Intent(this,ScanService.class),scanConnection,Context.BIND_AUTO_CREATE);}catch(Exception e){log("background scan unavailable");}}
    final Runnable wifiRepeater=new Runnable(){public void run(){if(phoneActive){scanWifi();scanHandler.postDelayed(this,30000);}}};
    static final long BLE_RESTART_MS=20*60*1000L; long bleScanStarted;
    final Runnable bleRepeater=new Runnable(){public void run(){if(!phoneActive)return;if(bleScanner!=null&&bleCallback!=null){try{bleScanner.stopScan(bleCallback);}catch(Exception ignored){}}phoneBleActive=false;startBleScan();log("BLE scan refreshed");scanHandler.postDelayed(this,BLE_RESTART_MS);}};
    void scanWifi(){wifiScanRequests++;try{if(wifiManager!=null&&wifiManager.isWifiEnabled()){if(!wifiManager.startScan())addWifiResults();}}catch(SecurityException e){log("Wi-Fi scan permission denied");}catch(Exception e){log("Wi-Fi scan unavailable");}}
    final BroadcastReceiver wifiReceiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){addWifiResults();}};
    boolean classicReceiverRegistered=false;
    // Phase 5 (§2): Bluetooth Classic discovery — real factory BD_ADDR -> reliable OUI, Class of Device, SDP UUIDs. Active ~12s inquiry, looped.
    final BroadcastReceiver classicReceiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){String a=i.getAction();if(android.bluetooth.BluetoothDevice.ACTION_FOUND.equals(a)){android.bluetooth.BluetoothDevice d=i.getParcelableExtra(android.bluetooth.BluetoothDevice.EXTRA_DEVICE);short rs=i.getShortExtra(android.bluetooth.BluetoothDevice.EXTRA_RSSI,(short)-127);String nm=i.getStringExtra(android.bluetooth.BluetoothDevice.EXTRA_NAME);if(d!=null)addClassicDevice(d,rs,nm);}else if(android.bluetooth.BluetoothAdapter.ACTION_DISCOVERY_FINISHED.equals(a)&&phoneActive){scanHandler.postDelayed(()->startClassicDiscovery(),15000);}}};
    void startClassicDiscovery(){try{if(Build.VERSION.SDK_INT>=31&&!hasPermission(android.Manifest.permission.BLUETOOTH_SCAN))return;BluetoothManager bm=(BluetoothManager)getSystemService(BLUETOOTH_SERVICE);BluetoothAdapter a=bm==null?null:bm.getAdapter();if(a==null||!a.isEnabled())return;if(a.isDiscovering())a.cancelDiscovery();a.startDiscovery();}catch(SecurityException e){log("Classic discovery permission denied");}catch(Exception e){log("Classic discovery unavailable");}}
    void addClassicDevice(android.bluetooth.BluetoothDevice dev,int rssi,String extraName){try{String mac=ObservationState.address(dev.getAddress());if(mac.isEmpty())return;boolean connect=Build.VERSION.SDK_INT<31||hasPermission(android.Manifest.permission.BLUETOOTH_CONNECT);Row r;synchronized(rows){String key="BTC |"+mac;r=rows.get(key);boolean first=r==null;if(r==null)r=new Row();r.mac=mac;r.kind="BTC ";r.source="PHONE";r.rssi=rssi;r.lastSeen=System.currentTimeMillis();if(first)r.firstSeen=r.lastSeen;r.count++;r.vendor=vendor(mac,false);r.oui=ouiPrefix(mac,false);if(extraName!=null&&!extraName.isEmpty())r.name=extraName;JSONObject raw=new JSONObject();raw.put("t","btc");raw.put("mac",mac);raw.put("rssi",rssi);String cls="";if(connect)try{android.bluetooth.BluetoothClass cod=dev.getBluetoothClass();if(cod!=null){cls=btMajor(cod.getMajorDeviceClass());raw.put("majorClass",cod.getMajorDeviceClass());raw.put("deviceClass",cod.getDeviceClass());raw.put("class",cls);}raw.put("type",btType(dev.getType()));android.os.ParcelUuid[] us=dev.getUuids();if(us!=null){StringBuilder uu=new StringBuilder();for(android.os.ParcelUuid u:us){if(uu.length()>0)uu.append(',');uu.append(u.toString());}raw.put("uuids",uu.toString());}if(r.name.isEmpty()){String nm=dev.getName();if(nm!=null)r.name=nm;}}catch(SecurityException ignored){}r.raw=raw;r.classification=cls.isEmpty()?"BLUETOOTH CLASSIC":"BLUETOOTH CLASSIC · "+cls;r.classificationEvidence="real BD_ADDR (active inquiry) → "+r.vendor;applyVendorTable(r);rows.put(key,r);evictRows();}logDevice(r);requestDraw();}catch(Exception ignored){}}
    String btMajor(int m){switch(m){case 256:return "Computer";case 512:return "Phone";case 768:return "Networking";case 1024:return "Audio/Video";case 1280:return "Peripheral";case 1536:return "Imaging";case 1792:return "Wearable";case 2048:return "Toy";case 2304:return "Health";default:return "Uncategorized";}}
    String btType(int t){switch(t){case 1:return "CLASSIC";case 2:return "LE";case 3:return "DUAL";default:return "?";}}
    void addWifiResults(){try{if(wifiManager==null)return;for(android.net.wifi.ScanResult s:wifiManager.getScanResults()){if(s.BSSID==null||s.BSSID.isEmpty())continue;JSONObject j=new JSONObject();j.put("t","wifi");j.put("_source","PHONE");j.put("mac",s.BSSID);j.put("rssi",s.level);j.put("ftype","ACCESS_POINT");j.put("name",s.SSID==null?"":s.SSID);j.put("frequencyMHz",s.frequency);j.put("channel",channelForFrequency(s.frequency));j.put("capabilities",s.capabilities);j.put("ageMs",Math.max(0,(SystemClock.elapsedRealtimeNanos()/1000-s.timestamp)/1000));j.put("timestampMicros",s.timestamp);if(Build.VERSION.SDK_INT>=30){j.put("channelWidth",s.channelWidth);j.put("centerFreq0",s.centerFreq0);j.put("centerFreq1",s.centerFreq1);j.put("wifiStandard",s.getWifiStandard());j.put("mcResponder",s.is80211mcResponder());StringBuilder ie=new StringBuilder();if(s.getInformationElements()!=null)for(android.net.wifi.ScanResult.InformationElement e:s.getInformationElements()){java.nio.ByteBuffer bb=e.getBytes();byte[] by=new byte[bb.remaining()];bb.get(by);if(ie.length()>0)ie.append(',');ie.append(e.getId()).append(':').append(hex(by));}j.put("informationElements",ie.toString());}parse(j.toString(),false);}runOnUiThread(()->draw());}catch(Exception ignored){}}
    int channelForFrequency(int f){if(f==2484)return 14;if(f>=2412&&f<=2472)return (f-2407)/5;if(f>=5000&&f<5925)return (f-5000)/5;if(f>=5955&&f<=7115)return (f-5950)/5;return 0;}
    void startBleScan(){phoneBleActive=false;try{BluetoothManager bm=(BluetoothManager)getSystemService(BLUETOOTH_SERVICE);BluetoothAdapter a=bm==null?null:bm.getAdapter();bleScanner=a==null?null:a.getBluetoothLeScanner();if(bleScanner==null){log("Bluetooth scan unavailable");return;}if(bleCallback!=null)bleScanner.stopScan(bleCallback);bleCallback=new ScanCallback(){@Override public void onScanResult(int type,android.bluetooth.le.ScanResult r){try{JSONObject j=new JSONObject();j.put("t","ble");j.put("_source","PHONE");j.put("mac",r.getDevice().getAddress());j.put("rssi",r.getRssi());j.put("callbackType",type);j.put("dataStatus",r.getDataStatus());j.put("legacy",r.isLegacy());j.put("primaryPhy",r.getPrimaryPhy());j.put("secondaryPhy",r.getSecondaryPhy());j.put("advertisingSid",r.getAdvertisingSid());j.put("txPower",r.getTxPower());j.put("timestampNanos",r.getTimestampNanos());j.put("_observedAt",System.currentTimeMillis()-Math.max(0,(SystemClock.elapsedRealtimeNanos()-r.getTimestampNanos())/1000000));ScanRecord rec=r.getScanRecord();if(rec!=null){String name=rec.getDeviceName();if(name!=null)j.put("name",name);StringBuilder m=new StringBuilder();for(byte[] v:manufacturerValues(rec)){if(m.length()>0)m.append(",");m.append(hex(v));}j.put("manufacturer",m.toString());ArrayList<String> uuids=new ArrayList<>();if(rec.getServiceUuids()!=null)for(android.os.ParcelUuid u:rec.getServiceUuids())uuids.add(u.toString().replace("-",""));j.put("services",String.join(",",uuids));j.put("txPowerLevel",rec.getTxPowerLevel());j.put("advertiseFlags",rec.getAdvertiseFlags());JSONObject serviceData=new JSONObject();for(Map.Entry<android.os.ParcelUuid,byte[]> e:rec.getServiceData().entrySet())serviceData.put(e.getKey().toString(),hex(e.getValue()));j.put("serviceData",serviceData);}parse(j.toString());}catch(Exception ignored){}}@Override public void onScanFailed(int error){runOnUiThread(()->{phoneBleActive=false;log("Bluetooth scan failed "+error);draw();});}};bleScanner.startScan(null,new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).setReportDelay(0).build(),bleCallback);phoneBleActive=true;bleScanStarted=SystemClock.elapsedRealtime();}catch(SecurityException e){log("Bluetooth scan permission denied");}catch(Exception e){log("Bluetooth scan unavailable");}}
    String hex(byte[] data){StringBuilder b=new StringBuilder();for(byte x:data)b.append(String.format(Locale.US,"%02X",x&255));return b.toString();}
    ArrayList<byte[]> manufacturerValues(ScanRecord r){ArrayList<byte[]> out=new ArrayList<>();android.util.SparseArray<byte[]> d=r.getManufacturerSpecificData();for(int i=0;i<d.size();i++){byte[] v=d.valueAt(i);byte[] full=new byte[v.length+2];int id=d.keyAt(i);full[0]=(byte)(id&255);full[1]=(byte)((id>>8)&255);System.arraycopy(v,0,full,2,v.length);out.add(full);}return out;}
    String detailLabel(String k){if(k.equals("name"))return "NAME";if(k.equals("services"))return "SERVICE UUIDS";if(k.equals("manufacturer"))return "MANUFACTURER DATA";if(k.equals("ftype"))return "FRAME TYPE";if(k.equals("frequencyMHz"))return "FREQUENCY MHz";if(k.equals("txPower"))return "TX POWER dBm";if(k.equals("serviceData"))return "SERVICE DATA";if(k.equals("capabilities"))return "CAPABILITIES";if(k.equals("ssid"))return "NETWORK NAME";if(k.equals("channel"))return "CHANNEL";if(k.equals("ageMs"))return "RADIO AGE";if(k.equals("timestampNanos"))return "RADIO TIMESTAMP";if(k.equals("advertiseFlags"))return "ADV FLAGS";return k.replaceAll("([a-z])([A-Z])","$1 $2").toUpperCase(Locale.ROOT);}
    String ageLabel(long timestamp){if(timestamp<=0)return "—";long seconds=Math.max(0,(System.currentTimeMillis()-timestamp)/1000);if(seconds<60)return seconds+" sec ago";if(seconds<3600)return seconds/60+" min ago";return seconds/3600+" hr ago";}
    View metricStrip(Row d){LinearLayout strip=new LinearLayout(this);strip.setPadding(0,5,0,6);String age=(System.currentTimeMillis()-d.lastSeen)/1000+"s";strip.addView(metric("RSSI",d.rssi+" dBm",d.kind.equals("BLE ")?BLUE:AMBER),new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams second=new LinearLayout.LayoutParams(0,-2,1);second.leftMargin=dp(5);strip.addView(metric("SEEN",String.valueOf(d.count),WHITE),second);LinearLayout.LayoutParams third=new LinearLayout.LayoutParams(0,-2,1);third.leftMargin=dp(5);strip.addView(metric("AGE",age,DIM),third);return strip;}
    View metric(String label,String value,int color){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(8),dp(7),dp(5),dp(7));box.setBackgroundColor(PANEL);TextView l=text(label,8,DIM,false);l.setLetterSpacing(0.06f);box.addView(l);TextView v=text(value,11,color,false);v.setPadding(0,dp(3),0,0);box.addView(v);return box;}
    void addCapturedData(Row d){if(d.raw!=null&&d.kind.trim().equals("WIFI")){String frame=d.raw.optString("ftype");if(frame.equalsIgnoreCase("probe_req")){String requested=d.raw.optString("ssid",d.raw.optString("name",""));metadataItem("PROBED SSID",requested.isEmpty()?"WILDCARD":requested);}else if(SignalClassifier.isNetworkIdentityFrame(frame)){String advertised=d.raw.optString("ssid",d.raw.optString("name",""));metadataItem("SSID",advertised.isEmpty()?"HIDDEN":advertised);}}if(d.raw==null){line("NO RADIO METADATA",DIM);return;}ArrayList<String> keys=new ArrayList<>();java.util.Iterator<String> it=d.raw.keys();while(it.hasNext()){String k=it.next();if(!k.startsWith("_")&&!k.equals("t")&&!k.equals("_source")&&!k.equals("mac")&&!k.equals("rssi")&&!k.equals("name")&&!k.equals("ssid")&&!k.equals("ageMs"))keys.add(k);}String[] priority={"ftype","channel","frequencyMHz","capabilities","manufacturer","services","serviceData","txPower","txPowerLevel","advertiseFlags","primaryPhy","secondaryPhy","legacy","callbackType","dataStatus","advertisingSid","timestampNanos"};keys.sort(Comparator.comparingInt((String k)->metadataOrder(k,priority)).thenComparing(String.CASE_INSENSITIVE_ORDER));if(keys.isEmpty()){line("NO ADDITIONAL RADIO FIELDS",DIM);return;}for(String k:keys){Object value=d.raw.opt(k);if(value==null||value==JSONObject.NULL)continue;String rendered=String.valueOf(value);if(rendered.isEmpty()||rendered.equals("-1")||rendered.equals("2147483647"))continue;metadataItem(detailLabel(k),rendered);}}
    int metadataOrder(String key,String[] priority){for(int i=0;i<priority.length;i++)if(priority[i].equals(key))return i;return priority.length;}
    void metadataItem(String key,String value){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.TOP);row.setPadding(0,dp(7),0,dp(7));TextView k=text(key,8,DIM,false);k.setLetterSpacing(0.035f);row.addView(k,new LinearLayout.LayoutParams(dp(112),-2));TextView v=text(value,9,WHITE,false);v.setSingleLine(false);v.setBreakStrategy(android.text.Layout.BREAK_STRATEGY_HIGH_QUALITY);row.addView(v,new LinearLayout.LayoutParams(0,-2,1));View divider=new View(this);divider.setBackgroundColor(GRID);LinearLayout cell=new LinearLayout(this);cell.setOrientation(1);cell.addView(row);cell.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));body.addView(cell);}
    int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+0.5f);}void section(String s){TextView t=text(s,10,GREEN,false);t.setLetterSpacing(0.07f);t.setTextSize(8);t.setPadding(0,dp(14),0,dp(9));body.addView(t);}void line(String s,int c){TextView t=text(s,10,c,false);t.setPadding(0,5,0,5);body.addView(t);}TextView card(String a,String b,int color){TextView t=text(a+"\n"+b,10,color,false);t.setPadding(10,8,10,8);t.setBackgroundColor(PANEL);t.setClickable(true);t.setFocusable(true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=5;body.addView(t,lp);return t;}
    void connect(){startForegroundService(new Intent(this,CydLinkService.class));}
    void send(String command){if(cydLink!=null)cydLink.send(command);else{log("CYD not connected");requestDraw();}}
    String advertisedServices(JSONObject json){StringBuilder services=new StringBuilder(json.optString("services",""));JSONObject data=json.optJSONObject("serviceData");if(data!=null){Iterator<String> keys=data.keys();while(keys.hasNext()){if(services.length()>0)services.append(",");services.append(keys.next());}}return services.toString();}
    SignalClassifier.Result classifyInApp(Row r,String typ,JSONObject j){String manufacturers=j.optString("manufacturer",""),services=advertisedServices(j);if(r.kind.trim().equals("BLE")){for(String block:PublicSafetyMatcher.manufacturerBlocks(manufacturers)){if(block.length()>=4&&block.length()%2==0&&block.matches("[0-9a-fA-F]+")){String company=block.substring(0,4).toUpperCase(Locale.ROOT);r.manufacturersSeen.put(company,block.toUpperCase(Locale.ROOT));while(r.manufacturersSeen.size()>16)r.manufacturersSeen.remove(r.manufacturersSeen.keySet().iterator().next());}}for(String value:services.split("[,;\\s]+")){String uuid=PublicSafetyMatcher.uuid(value);if(!uuid.isEmpty())r.servicesSeen.add(uuid);}while(r.servicesSeen.size()>64)r.servicesSeen.remove(r.servicesSeen.iterator().next());manufacturers=String.join(",",r.manufacturersSeen.values());services=String.join(",",r.servicesSeen);}return SignalClassifier.classify(r.kind,r.vendor,ouiTypes.get(r.oui),r.oui,j.optString("ftype","UNKNOWN"),r.name,manufacturers,services,r.kind.trim().equals("BLE")||r.networkIdentityName);}
    void parse(String s){parse(s,true);}void parse(String s,boolean redraw){try{JSONObject j=new JSONObject(s);String typ=j.optString("t","");if("wifi_control".equals(typ)){controls+=j.optInt("count",1);log("WIFI CONTROL "+j.optString("ftype","")+" ×"+j.optInt("count",1)+" CH "+j.optInt("ch",0));}
            else if("wifi".equals(typ)||"ble".equals(typ)){
                String mac=ObservationState.address(j.optString("mac"));if(mac.isEmpty())return;
                String kind="wifi".equals(typ)?"WIFI":"BLE ",key=kind+"|"+mac;Row r;boolean first;ObservationState.Sample sample;
                synchronized(rows){r=rows.get(key);if(r==null)r=new Row();first=r.count==0;sample=r.observations.accept(j,System.currentTimeMillis());if(sample==null)return;
                    boolean isBle=kind.trim().equals("BLE");r.mac=mac;r.kind=kind;r.rssi=r.observations.rssi;r.vendor=vendor(mac,isBle);r.oui=ouiPrefix(mac,isBle);
                    String observedName=j.optString("name",j.optString("ssid",""));if(!observedName.isEmpty()&&sample.observedAt>=r.nameObservedAt){if(kind.trim().equals("BLE")){r.name=observedName;r.nameObservedAt=sample.observedAt;}else if(SignalClassifier.isNetworkIdentityFrame(j.optString("ftype"))&&!observedName.equalsIgnoreCase("<unknown ssid>")){r.name=observedName;r.networkIdentityName=true;r.nameObservedAt=sample.observedAt;}}
                    SignalClassifier.Result result=classifyInApp(r,typ,j);r.classification=result.label;r.classificationEvidence=result.evidence;r.camera=result.camera;r.tracker=result.tracker;r.publicSafety=result.publicSafety;applyVendorTable(r);applyDeviceIntel(r);
                    r.source=r.observations.sourceLabel();r.firstSeen=r.observations.firstSeen;r.lastSeen=r.observations.lastSeen;r.count=r.observations.count;r.raw=r.observations.metadata();applyHotspot(r);r.extra=r.classification+(r.name.isEmpty()?"":" · "+r.name);rows.put(key,r);evictRows();}
                if("wifi".equals(typ)){wifi++;if(sample.source.equals("PHONE"))phoneWifiAccepted++;else cydWifiAccepted++;}else{ble++;if(sample.source.equals("PHONE"))phoneBleAccepted++;else cydBleAccepted++;}
                addSignalPoint(kind.trim(),sample.rssi,mac,sample.source,sample.observedAt);if(first){if(kind.trim().equals("BLE"))noteBleAddress(mac);log(kind+" "+mac+" "+r.vendor);}
                feedTrackerDetection(r);logDevice(r);feedFinder(r);
            }
            else if(j.has("_status")&&j.optString("_status").equals("alive")){}
            else if(j.has("_status")&&j.optString("_status").contains("boot")){}
            else if(j.has("_millie")){if(j.optString("_millie").equals("touch")){touchReady=j.optBoolean("ready",false);touchCalibrated=j.optBoolean("calibrated",false);touchController=j.optString("controller","UNKNOWN");log("touch: "+s);}else if(j.optString("_millie").equals("attack")){handleAttackReport(j);}else log("millie: "+s);}
            else if(j.has("_status")){log(j.optString("_status")+": "+j.optString("cmd",""));}
            if(redraw&&!page.equals("MORE")&&!page.equals("LOG")&&!page.equals("LINK")&&!page.equals("FINDER"))requestDraw();}catch(Exception ignored){}}
    void addSignalPoint(String kind,int rssi,String mac,String source,long observedAt){long now=System.currentTimeMillis();if(now-observedAt>60000)return;synchronized(signalHistory){signalHistory.addLast(new SignalPoint(observedAt,rssi,kind,mac,source));signalHistory.removeIf(point->now-point.time>60000);while(signalHistory.size()>2000)signalHistory.removeFirst();}}
    synchronized void requestDraw(){if(activityDestroyed||drawQueued)return;drawQueued=true;scanHandler.postDelayed(()->{synchronized(MainActivity.this){drawQueued=false;}draw();},250);}
    void log(String s){synchronized(logs){logs.add(String.format(Locale.US,"%tT  %s",new Date(),s));while(logs.size()>200)logs.remove(0);} }
    @Override public void dump(String prefix,java.io.FileDescriptor fd,java.io.PrintWriter out,String[] args){super.dump(prefix,fd,out,args);out.println(prefix+"SWIVEL_SCAN phoneEnabled="+phoneActive+" bleRunning="+phoneBleActive+" cydLive="+gotAlive+" wifiRequests="+wifiScanRequests+" phoneWifi="+phoneWifiAccepted+" phoneBle="+phoneBleAccepted+" cydWifi="+cydWifiAccepted+" cydBle="+cydBleAccepted);int dual=0;for(Row row:snapshot())if(row.observations.sources.size()>1)dual++;out.println(prefix+"SWIVEL_MERGE contacts="+snapshot().size()+" shared="+dual);}
    @Override protected void onDestroy(){activityDestroyed=true;if(finderView!=null){finderView.stop();finderView=null;}if(cydLink!=null)cydLink.unregister(this);try{unbindService(serviceConnection);}catch(Exception ignored){}cydLink=null;if(scanService!=null)scanService.unregister(this);if(scanServiceBound)try{unbindService(scanConnection);}catch(Exception ignored){}scanService=null;scanServiceBound=false;if(wifiReceiverRegistered)try{unregisterReceiver(wifiReceiver);}catch(Exception ignored){}if(classicReceiverRegistered)try{unregisterReceiver(classicReceiver);}catch(Exception ignored){}try{BluetoothManager bm=(BluetoothManager)getSystemService(BLUETOOTH_SERVICE);if(bm!=null&&bm.getAdapter()!=null&&bm.getAdapter().isDiscovering())bm.getAdapter().cancelDiscovery();}catch(Exception ignored){}scanHandler.removeCallbacksAndMessages(null);if(bleScanner!=null&&bleCallback!=null)try{bleScanner.stopScan(bleCallback);}catch(Exception ignored){}super.onDestroy();}
